public class Main {
    public static void main(String[] args) {
        HinhChuNhat h = new HinhChuNhat(5, 3);
        System.out.println(h.dienTich());
    }
}

class HinhChuNhat {
    int dai, rong;
    HinhChuNhat(int d, int r) {
        dai = d;
        rong = r;
    }
    int dienTich() { return dai * rong; }
}
